		AuthID: authID,
	})
	// 版税按所属系列的规则快照计算；余款归转让前持有人。
	it := r.state.Items[itemID]
	royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
		r.state.Series[it.SeriesID].Royalty, from)
