		Entries: []TransferBatchEntry{
			{ItemID: "i5", ToID: "dave", ExpectedOwner: "carol", ExpectedVer: 1},
			{ItemID: "i1", ToID: "dave", ExpectedOwner: "carol", ExpectedVer: 1},
